:root {
  --ink: #eaf7ff;
  --muted: #8ba0b8;
  --dim: #576d86;
  --cyan: #5ef4ff;
  --magenta: #ff4fd8;
  --amber: #ffd166;
  --lime: #a8ff78;
  --panel: rgba(7, 13, 26, 0.78);
  --line: rgba(120, 221, 255, 0.22);
  --mono: "SFMono-Regular", "Cascadia Code", "Roboto Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  min-height: 100%;
  overflow: hidden;
  background: #03050c;
  color: var(--ink);
  font-family: "Segoe UI", Inter, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

body {
  display: grid;
  place-items: center;
  min-height: 100dvh;
  background:
    radial-gradient(circle at 18% 0%, rgba(71, 47, 186, 0.24), transparent 42%),
    radial-gradient(circle at 88% 100%, rgba(220, 42, 154, 0.14), transparent 48%),
    #03050c;
}

button { font: inherit; color: inherit; }

#app {
  position: relative;
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
  background: #050812;
  isolation: isolate;
  user-select: none;
  touch-action: none;
}

#game {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
}

.sky-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 10%, rgba(76, 119, 255, 0.18), transparent 48%),
    linear-gradient(180deg, rgba(8, 12, 25, 0.12), transparent 32%);
  mix-blend-mode: screen;
  z-index: 2;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background:
    radial-gradient(ellipse at center, transparent 48%, rgba(2, 4, 10, 0.5) 100%),
    linear-gradient(180deg, rgba(2, 4, 9, 0.45), transparent 18%, transparent 78%, rgba(2, 4, 9, 0.55));
}

.scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  opacity: 0.32;
  background: repeating-linear-gradient(180deg, rgba(130, 220, 255, 0.035) 0 1px, transparent 1px 4px);
  mix-blend-mode: screen;
}

#flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 18;
  opacity: 0;
  background: radial-gradient(ellipse at center, rgba(255, 70, 120, 0.05), rgba(255, 60, 110, 0.42));
  transition: opacity 120ms ease-out;
}
#flash.on { opacity: 1; transition: none; }

/* ---------------- HUD ---------------- */

.hud {
  position: absolute;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity 220ms ease, transform 220ms ease;
}

#app[data-state="countdown"] .hud,
#app[data-state="race"] .hud,
#app[data-state="finished"] .hud {
  opacity: 1;
  transform: none;
}

.hud-top {
  top: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 20px 96px 40px 24px;
  background: linear-gradient(180deg, rgba(2, 5, 12, 0.62), transparent);
}

.hud-cluster {
  min-width: 0;
  padding: 7px 12px 8px;
  border-left: 1px solid rgba(94, 244, 255, 0.42);
  background: linear-gradient(90deg, rgba(5, 11, 23, 0.72), rgba(5, 11, 23, 0.06));
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.7);
}

.label {
  display: block;
  color: #8fb7cc;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  margin-bottom: 1px;
  white-space: nowrap;
}

.big {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: 0.01em;
  line-height: 1;
  white-space: nowrap;
}

.big b {
  font-weight: 900;
  color: #fff;
  font-size: 30px;
  letter-spacing: -0.03em;
}

.big i { font-style: normal; color: #67839c; font-size: 12px; font-weight: 700; letter-spacing: 0.08em; }

.mono { font-family: var(--mono); font-variant-numeric: tabular-nums; font-size: 20px; letter-spacing: -0.02em; }

.timebox { min-width: 144px; }
.timebox .mono { color: #dffbff; }

.gatebox { width: 150px; margin-top: 2px; }
.gate-meter { height: 3px; margin: 6px 0 5px; background: rgba(129, 208, 238, 0.15); overflow: hidden; }
.gate-meter i {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--cyan), var(--amber));
  box-shadow: 0 0 10px rgba(94, 244, 255, 0.8);
  transition: width 140ms linear;
}
.gate-count { color: #7c9aaf; font-family: var(--mono); font-size: 10px; letter-spacing: 0.12em; }

.posbox { margin-left: auto; }
.posbox .big b { color: var(--amber); }
.scorebox { min-width: 152px; text-align: right; border-left: 0; border-right: 1px solid rgba(255, 79, 216, 0.34); padding-right: 14px; background: linear-gradient(270deg, rgba(16, 7, 25, 0.72), rgba(5, 11, 23, 0.04)); }
.scorebox .big { justify-content: flex-end; color: #fff3fb; }
.scorebox .big.mono { font-size: 25px; color: #ffe9fb; text-shadow: 0 0 18px rgba(255, 79, 216, 0.4); }
.combo {
  margin-top: 3px;
  color: var(--magenta);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  transition: transform 120ms ease;
}
.combo.hot { transform: scale(1.12); color: var(--amber); }

.tools {
  position: absolute;
  top: 18px;
  right: 18px;
  z-index: 30;
  display: flex;
  gap: 7px;
}

.icon-btn {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(107, 205, 242, 0.22);
  border-radius: 8px;
  background: rgba(4, 9, 19, 0.64);
  color: #8fc5d9;
  cursor: pointer;
  backdrop-filter: blur(8px);
  transition: border-color 140ms, color 140ms, background 140ms;
}
.icon-btn:hover { border-color: rgba(94, 244, 255, 0.65); color: #eaffff; background: rgba(11, 23, 38, 0.8); }
.icon-btn svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
