.icon-btn.muted::after { content: ""; position: absolute; width: 20px; height: 1.5px; background: #ff6d93; transform: rotate(-45deg); }
.icon-btn { position: relative; overflow: hidden; }
#pauseBtn { display: none; }
#app[data-state="race"] #pauseBtn,
#app[data-state="countdown"] #pauseBtn { display: grid; }

.hud-bottom {
  bottom: 0;
  align-items: flex-end;
