}

.speedbox { width: 218px; min-width: 0; }
.speed-row { display: flex; align-items: flex-end; justify-content: space-between; }
.speed-read { display: flex; align-items: baseline; gap: 6px; }
.speed-read b {
  font-size: 48px;
  line-height: 0.82;
  font-weight: 900;
  letter-spacing: -0.06em;
  font-variant-numeric: tabular-nums;
  color: #f5fdff;
  text-shadow: 0 0 24px rgba(94, 244, 255, 0.28);
}
.speed-read span { color: #6e9ab0; font-size: 9px; font-weight: 800; letter-spacing: 0.16em; }
.gear {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(94, 244, 255, 0.34);
  border-radius: 6px;
