  font-weight: 800;
  background: rgba(5, 20, 30, 0.5);
  box-shadow: inset 0 0 12px rgba(94, 244, 255, 0.08);
}
.revbar { height: 4px; margin-top: 10px; background: rgba(119, 200, 230, 0.15); transform: skewX(-18deg); overflow: hidden; }
.revbar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #48dfff, #ffce68 72%, #ff4f6d); box-shadow: 0 0 12px rgba(94, 244, 255, 0.6); }
.speed-hint { margin-top: 6px; color: #547086; font-size: 8px; font-weight: 800; letter-spacing: 0.2em; }

.driftbox { width: min(360px, 34vw); margin-bottom: 4px; text-align: center; }
.drift-label {
  color: #87aebf;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.22em;
  margin-bottom: 7px;
  transition: color 140ms, text-shadow 140ms;
}
.drift-label.active { color: var(--magenta); text-shadow: 0 0 16px rgba(255, 79, 216, 0.65); animation: pulseText 520ms ease-in-out infinite alternate; }
.drift-label.boost { color: var(--cyan); text-shadow: 0 0 18px rgba(94, 244, 255, 0.8); }
@keyframes pulseText { to { opacity: 0.66; } }

.drift-bar {
  position: relative;
  height: 9px;
  border: 1px solid rgba(94, 244, 255, 0.24);
  background: rgba(4, 13, 24, 0.72);
  transform: skewX(-18deg);
  overflow: hidden;
}
.drift-bar i {
  position: absolute;
  inset: 1px;
  width: 0%;
  background: linear-gradient(90deg, #1a8fa4, var(--cyan) 54%, #c8feff);
  box-shadow: 0 0 16px rgba(94, 244, 255, 0.7);
  transition: width 90ms linear;
}
.drift-bar.boosting i { background: linear-gradient(90deg, #ff4fd8, #ffd166, #fff); box-shadow: 0 0 18px rgba(255, 79, 216, 0.8); }
.drift-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 25%, rgba(5, 8, 16, 0.7) 25% 26%);
}
.drift-hint { display: flex; justify-content: space-between; margin-top: 5px; color: #58768a; font-family: var(--mono); font-size: 8px; letter-spacing: 0.14em; }
.drift-hint span:last-child { color: #9cc8d8; }

.mapbox { position: relative; width: 140px; height: 126px; }
#minimap { width: 140px; height: 116px; display: block; opacity: 0.92; }
.map-label { position: absolute; left: 2px; bottom: 0; color: #5f7f92; font-size: 7px; font-weight: 800; letter-spacing: 0.18em; }

