/* ---------------- Overlays ---------------- */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: none;
  overflow-y: auto;
  overscroll-behavior: contain;
}

#app[data-state="menu"] .menu { display: flex; }
#app[data-state="paused"] .pause { display: flex; }
#app[data-state="finished"] .results { display: flex; }

.menu {
  align-items: center;
  gap: 30px;
  padding: 26px clamp(20px, 5vw, 72px);
  background:
    linear-gradient(90deg, rgba(3, 6, 14, 0.88) 0%, rgba(3, 7, 16, 0.58) 42%, rgba(3, 7, 16, 0.04) 72%),
    radial-gradient(ellipse at 72% 48%, transparent 10%, rgba(2, 5, 12, 0.22) 80%);
}

.menu-card {
  position: relative;
  width: min(544px, 100%);
  padding: 30px 34px 26px;
  border: 1px solid rgba(111, 214, 244, 0.2);
  border-left: 2px solid rgba(94, 244, 255, 0.82);
  background:
    linear-gradient(135deg, rgba(11, 19, 36, 0.88), rgba(6, 10, 22, 0.76) 58%, rgba(22, 8, 31, 0.66));
  box-shadow: 0 34px 100px rgba(0, 0, 0, 0.58), inset 0 0 60px rgba(49, 110, 180, 0.07);
  backdrop-filter: blur(14px);
  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 0 100%);
}
.menu-card::after {
  content: "";
  position: absolute;
  top: 0;
  right: 26px;
  width: 1px;
  height: 26px;
  background: rgba(94, 244, 255, 0.42);
  transform: rotate(-45deg);
  transform-origin: top right;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #79a0b6;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.28em;
  text-transform: uppercase;
}
.eyebrow span { height: 1px; width: 24px; background: currentColor; opacity: 0.5; }

.logo {
  margin: 12px 0 8px;
  font-family: "Arial Black", "Trebuchet MS", Impact, sans-serif;
  font-size: clamp(58px, 8.2vw, 92px);
  font-weight: 900;
  font-style: italic;
  line-height: 0.79;
  letter-spacing: -0.075em;
  text-transform: uppercase;
  color: #f4fdff;
  text-shadow: 0 0 26px rgba(94, 244, 255, 0.34), 0 16px 50px rgba(0, 0, 0, 0.55);
}
.logo em {
  display: inline-block;
  padding-right: 0.06em;
  font-style: inherit;
  background: linear-gradient(96deg, var(--magenta) 4%, #bd8bff 48%, var(--cyan) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 22px rgba(255, 79, 216, 0.28));
}

.tagline {
  margin: 14px 0 20px;
  max-width: 350px;
  color: #9ab4c7;
  font-size: 13px;
  line-height: 1.55;
  letter-spacing: 0.02em;
}

.primary, .secondary, .ghost {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 50px;
  padding: 0 24px;
  border: 0;
  border-radius: 2px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: transform 140ms ease, box-shadow 140ms ease, background 140ms ease, color 140ms ease;
}
.primary {
  color: #041018;
  background: linear-gradient(96deg, #7ff8ff, #5ef4ff 46%, #bdfcff);
  box-shadow: 0 0 0 1px rgba(140, 248, 255, 0.3), 0 12px 34px rgba(36, 191, 224, 0.24);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
}
.primary:hover { transform: translateY(-1px); box-shadow: 0 0 0 1px rgba(180, 252, 255, 0.6), 0 16px 44px rgba(58, 220, 255, 0.34); }
.primary:active { transform: translateY(1px) scale(0.995); }
.secondary {
  color: #dff9ff;
  border: 1px solid rgba(94, 244, 255, 0.45);
  background: rgba(14, 36, 52, 0.55);
}
.secondary:hover { background: rgba(24, 60, 82, 0.7); }
.ghost {
  color: #8ba5b8;
  border: 1px solid rgba(122, 158, 184, 0.22);
  background: transparent;
}
.ghost:hover { color: #e9fbff; border-color: rgba(142, 210, 235, 0.55); }

#startBtn { width: 100%; justify-content: space-between; padding: 0 18px 0 24px; }
#startBtn kbd {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border: 1px solid rgba(2, 24, 33, 0.26);
  border-radius: 3px;
  background: rgba(3, 27, 37, 0.14);
  color: rgba(3, 24, 32, 0.78);
  font-family: var(--mono);
  font-size: 13px;
}

.menu-controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 16px;
  margin: 20px 0 18px;
  padding-top: 16px;
  border-top: 1px solid rgba(111, 197, 230, 0.14);
}
.menu-controls > div { display: flex; align-items: center; gap: 9px; min-width: 0; }
.menu-controls > div > span:last-child { color: #87a4b9; font-size: 9px; letter-spacing: 0.08em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.keys { display: flex; gap: 3px; flex-shrink: 0; }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 19px;
  height: 19px;
  padding: 0 4px;
  border: 1px solid rgba(124, 198, 226, 0.25);
  border-bottom-color: rgba(94, 244, 255, 0.5);
  border-radius: 3px;
  background: rgba(13, 27, 43, 0.8);
  color: #c7eaf5;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
}

.menu-footer {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px 18px;
  padding-top: 14px;
  border-top: 1px solid rgba(111, 197, 230, 0.14);
}
.menu-footer > div > span { display: block; color: #5d7b8f; font-size: 7px; font-weight: 800; letter-spacing: 0.18em; margin-bottom: 2px; }
.menu-footer > div > b { color: #d7f6ff; font-family: var(--mono); font-size: 13px; font-weight: 700; letter-spacing: 0.01em; }
.menu-footer .tip { grid-column: 1 / -1; color: #7090a3; font-size: 9px; line-height: 1.5; margin-top: 2px; }
.menu-footer .tip b { color: #b8eaff; }

.menu-side {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-left: auto;
  align-self: flex-end;
  padding-bottom: 24px;
}
.side-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #7c9db0;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.85;
}
.side-chip b {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--cyan);
  border: 1px solid rgba(94, 244, 255, 0.25);
  padding: 4px 6px;
  background: rgba(5, 18, 28, 0.5);
}

.pause, .results {
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(2, 5, 12, 0.66);
  backdrop-filter: blur(7px);
}

.panel {
  position: relative;
  width: min(430px, 100%);
  padding: 34px 36px 30px;
  border: 1px solid rgba(109, 198, 230, 0.22);
  border-top: 2px solid rgba(94, 244, 255, 0.7);
  background: linear-gradient(150deg, rgba(11, 19, 36, 0.96), rgba(7, 11, 24, 0.96));
  box-shadow: 0 34px 100px rgba(0, 0, 0, 0.6);
  text-align: center;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
}
.panel::after {
  content: "";
  position: absolute;
  top: 0; right: 30px;
  width: 70px; height: 1px;
  background: var(--magenta);
  box-shadow: 0 0 14px rgba(255, 79, 216, 0.8);
}
.panel .eyebrow { justify-content: center; }
.panel h2 {
  margin: 14px 0 6px;
  font-family: "Arial Black", "Trebuchet MS", Impact, sans-serif;
  font-size: 42px;
  font-style: italic;
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.04em;
}
.panel-sub { margin: 0 0 22px; color: #86a5b9; font-size: 11px; line-height: 1.5; }
.button-stack { display: grid; gap: 9px; }
.button-stack .primary, .button-stack .secondary, .button-stack .ghost { width: 100%; }

.result-panel { width: min(480px, 100%); }
#resultTitle {
  font-size: 74px;
  color: var(--amber);
  background: linear-gradient(180deg, #fff6d8, #ffd166 62%, #ff9b54);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 40px rgba(255, 177, 66, 0.2);
}
.result-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  margin: 0 0 16px;
  background: rgba(112, 185, 213, 0.14);
  border: 1px solid rgba(112, 185, 213, 0.14);
}
.result-grid > div { padding: 14px 10px 12px; background: rgba(5, 11, 22, 0.92); }
.result-grid span { display: block; color: #658397; font-size: 7px; font-weight: 800; letter-spacing: 0.18em; margin-bottom: 4px; }
.result-grid b { display: block; color: #e7faff; font-family: var(--mono); font-size: 17px; letter-spacing: -0.02em; }
.new-best {
  display: none;
  margin: 0 0 14px;
  color: var(--lime);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-shadow: 0 0 16px rgba(168, 255, 120, 0.5);
}
.new-best.show { display: block; animation: newBest 1s ease-in-out infinite alternate; }
@keyframes newBest { from { opacity: 0.55; } to { opacity: 1; } }
.button-row { display: flex; gap: 10px; }
.button-row .primary { flex: 1; }

/* ---------------- Countdown, toasts, popups ---------------- */

.countdown {
  position: absolute;
  inset: 0;
  z-index: 17;
  display: none;
  place-items: center;
  pointer-events: none;
}
.countdown.show { display: grid; }
.countdown span {
  display: block;
  font-family: "Arial Black", "Trebuchet MS", Impact, sans-serif;
  font-size: clamp(150px, 26vw, 300px);
  font-weight: 900;
  font-style: italic;
  line-height: 0.8;
  color: #f4feff;
  text-shadow: 0 0 30px rgba(94, 244, 255, 0.7), 0 0 90px rgba(94, 244, 255, 0.3), 0 20px 50px rgba(0, 0, 0, 0.5);
  transform: translateY(-4%);
}
.countdown span.go { color: var(--amber); text-shadow: 0 0 34px rgba(255, 209, 102, 0.8), 0 0 100px rgba(255, 79, 216, 0.4); }
.countdown small { position: absolute; bottom: 29%; color: #8cc5d8; font-size: 10px; font-weight: 800; letter-spacing: 0.42em; opacity: 0; }
.countdown.pop span { animation: countPop 480ms cubic-bezier(0.16, 1, 0.3, 1); }
@keyframes countPop { 0% { transform: scale(1.7) translateY(-4%); opacity: 0; filter: blur(3px); } 100% { transform: scale(1) translateY(-4%); opacity: 1; filter: blur(0); } }

.toast {
  position: absolute;
  top: 23%;
  left: 50%;
  z-index: 19;
  transform: translate(-50%, -10px);
  opacity: 0;
  padding: 8px 16px;
  border: 1px solid rgba(94, 244, 255, 0.28);
  background: rgba(5, 15, 27, 0.82);
  color: #c9f7ff;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  pointer-events: none;
  transition: opacity 180ms ease, transform 180ms ease;
  backdrop-filter: blur(6px);
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.warn { border-color: rgba(255, 79, 216, 0.45); color: #ffd7f6; }

.popups { position: absolute; inset: 0; z-index: 15; pointer-events: none; overflow: hidden; }
.scorepop {
  position: absolute;
  transform: translate(-50%, -50%);
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--cyan);
  text-shadow: 0 0 14px rgba(94, 244, 255, 0.7), 0 2px 8px rgba(0, 0, 0, 0.8);
  animation: scoreFloat 900ms ease-out forwards;
  white-space: nowrap;
}
.scorepop.drift { color: var(--magenta); text-shadow: 0 0 14px rgba(255, 79, 216, 0.75), 0 2px 8px rgba(0, 0, 0, 0.8); }
.scorepop.crash { color: #ff829d; font-size: 16px; }
@keyframes scoreFloat {
  0% { opacity: 0; transform: translate(-50%, -30%) scale(0.7); }
  18% { opacity: 1; transform: translate(-50%, -60%) scale(1.08); }
  100% { opacity: 0; transform: translate(-50%, -170%) scale(0.94); }
}

.hint-menu { display: none; }

/* ---------------- Touch ---------------- */

.touch-controls {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 14px;
  z-index: 24;
  display: none;
  align-items: flex-end;
  justify-content: space-between;
  padding: 0 14px;
  pointer-events: none;
}
.touch-steer, .touch-pedals { display: flex; align-items: flex-end; gap: 9px; pointer-events: auto; }
.touch-btn {
  -webkit-tap-highlight-color: transparent;
  border: 1px solid rgba(107, 214, 247, 0.4);
  background: rgba(6, 18, 31, 0.62);
  color: #d7f7ff;
  border-radius: 50%;
  width: 62px;
  height: 62px;
  display: grid;
  place-items: center;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.04em;
  backdrop-filter: blur(7px);
  box-shadow: inset 0 0 20px rgba(70, 193, 230, 0.08), 0 8px 22px rgba(0, 0, 0, 0.35);
  touch-action: none;
}
.touch-btn.pressed { background: rgba(24, 83, 107, 0.8); border-color: rgba(137, 248, 255, 0.9); transform: scale(0.96); box-shadow: 0 0 22px rgba(94, 244, 255, 0.36); }
.touch-btn.gas { width: 78px; height: 78px; color: #061118; background: linear-gradient(160deg, #7ef8ff, #41d7e9); border: 0; font-size: 13px; box-shadow: 0 0 28px rgba(94, 244, 255, 0.28); }
.touch-btn.drift { color: #ffd3f4; border-color: rgba(255, 79, 216, 0.5); }
.touch-btn.small { width: 48px; height: 48px; font-size: 9px; }
.touch-btn.steer { font-family: sans-serif; font-size: 20px; }

@media (hover: none), (max-width: 760px) {
  .touch-controls { display: flex; }
  #app[data-state="menu"] .touch-controls,
  #app[data-state="paused"] .touch-controls,
  #app[data-state="finished"] .touch-controls { display: none; }
}

/* ---------------- Responsive ---------------- */

@media (min-width: 900px) and (min-height: 600px) {
  #app {
    width: min(96vw, 1240px);
    height: min(94vh, 790px);
    border: 1px solid rgba(104, 194, 228, 0.18);
    border-radius: 18px;
    box-shadow: 0 40px 120px rgba(0, 0, 0, 0.62), 0 0 0 1px rgba(4, 9, 20, 0.9) inset;
  }
  #app > canvas, #app > .sky-glow, #app > .vignette, #app > .scanlines { border-radius: 18px; }
}

@media (max-width: 1050px) {
  .menu-side { display: none; }
  .menu-card { margin: 0 auto; }
  .menu { justify-content: center; background: radial-gradient(ellipse at center, rgba(3, 7, 16, 0.5), rgba(2, 5, 12, 0.7)); }
  .hud-top { gap: 4px; padding-left: 18px; padding-right: 88px; }
  .hud-bottom { padding-left: 18px; padding-right: 18px; }
  .gatebox { display: none; }
}

@media (max-width: 820px) {
  .hud-top { padding-top: 14px; padding-left: 14px; padding-right: 82px; }
  .hud-cluster { padding: 5px 8px 6px; }
  .label { font-size: 7px; }
  .big { font-size: 19px; }
  .big b { font-size: 23px; }
  .timebox { min-width: 0; }
  .mono { font-size: 16px; }
  .posbox { display: none; }
  .scorebox { min-width: 106px; }
  .scorebox .big.mono { font-size: 18px; }
  .scorebox .combo { font-size: 9px; }
  .tools { top: 12px; right: 12px; }
  .hud-bottom { gap: 10px; padding: 38px 14px 18px; align-items: flex-end; }
  .speedbox { width: 126px; }
  .speed-read b { font-size: 36px; }
  .speed-read span, .speed-hint { font-size: 7px; }
  .driftbox { width: min(210px, 42vw); }
  .mapbox { display: none; }
  .menu { padding: 16px; align-items: flex-start; }
  .menu-card { padding: 24px 22px 20px; margin-top: max(8px, 3vh); }
  .logo { font-size: clamp(52px, 13vw, 72px); }
  .tagline { font-size: 12px; margin-bottom: 16px; }
  .menu-controls { gap: 7px 10px; margin: 16px 0 14px; }
  .menu-controls > div > span:last-child { font-size: 8px; }
  .menu-footer { gap: 8px 12px; }
  .menu-footer .tip { font-size: 8px; }
  .panel { padding: 28px 22px 24px; }
  .panel h2 { font-size: 34px; }
  #resultTitle { font-size: 60px; }
  .countdown span { font-size: clamp(130px, 34vw, 220px); }
}

@media (max-width: 760px) {
  .hud-bottom { bottom: 106px; padding-bottom: 8px; background: linear-gradient(0deg, rgba(2, 5, 12, 0.55), transparent); }
  .driftbox { margin-bottom: 0; }
  .speedbox { opacity: 0.92; }
  .speed-read b { font-size: 32px; }
  .toast { top: 17%; }
}

@media (max-width: 520px) {
  .menu-card { border-left-width: 1px; padding: 20px 18px 16px; }
  .eyebrow { font-size: 7px; letter-spacing: 0.2em; }
  .logo { font-size: 54px; }
  .tagline { max-width: 290px; }
  .menu-controls { grid-template-columns: 1fr 1fr; }
  .menu-controls > div > span:last-child { display: none; }
  .menu-footer > div > b { font-size: 11px; }
  .menu-footer .tip { display: none; }
  .hud-top { padding-right: 76px; }
  .lapbox { min-width: 44px; }
  .hud-cluster { background: rgba(5, 11, 23, 0.4); }
  .speedbox { width: 86px; }
  .speed-read b { font-size: 28px; }
  .speed-read span { display: none; }
  .gear { width: 24px; height: 24px; font-size: 12px; }
  .driftbox { width: 42vw; }
  .drift-label { font-size: 8px; letter-spacing: 0.12em; }
  .drift-hint { font-size: 7px; }
  .touch-btn { width: 56px; height: 56px; }
  .touch-btn.small { width: 44px; height: 44px; }
  .touch-btn.gas { width: 70px; height: 70px; }
  .panel { padding: 24px 18px 20px; }
  .button-row { flex-direction: column-reverse; }
  .button-row .primary { width: 100%; }
  .result-grid b { font-size: 14px; }
}

@media (max-height: 650px) and (min-width: 761px) {
  .menu-card { padding: 20px 24px 16px; }
  .logo { font-size: 58px; }
  .tagline { margin: 8px 0 12px; }
  .menu-controls { margin: 12px 0 10px; padding-top: 10px; }
  .menu-footer { padding-top: 10px; }
  .countdown span { font-size: 170px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

files.patch:
Index: styles.css
===================================================================
--- styles.css
+++ styles.css
@@ -312,6 +312,515 @@
 .mapbox { position: relative; width: 140px; height: 126px; }
 #minimap { width: 140px; height: 116px; display: block; opacity: 0.92; }
 .map-label { position: absolute; left: 2px; bottom: 0; color: #5f7f92; font-size: 7px; font-weight: 800; letter-spacing: 0.18em; }

-/* ---------------- HUD marker for JS ---------------- */
-/* part-two */
+/* ---------------- Overlays ---------------- */
+
+.overlay {
+  position: absolute;
+  inset: 0;
+  z-index: 20;
+  display: none;
+  overflow-y: auto;
+  overscroll-behavior: contain;
+}
+
+#app[data-state="menu"] .menu { display: flex; }
+#app[data-state="paused"] .pause { display: flex; }
+#app[data-state="finished"] .results { display: flex; }
+
+.menu {
+  align-items: center;
+  gap: 30px;
+  padding: 26px clamp(20px, 5vw, 72px);
+  background:
+    linear-gradient(90deg, rgba(3, 6, 14, 0.88) 0%, rgba(3, 7, 16, 0.58) 42%, rgba(3, 7, 16, 0.04) 72%),
+    radial-gradient(ellipse at 72% 48%, transparent 10%, rgba(2, 5, 12, 0.22) 80%);
+}
+
+.menu-card {
+  position: relative;
+  width: min(544px, 100%);
+  padding: 30px 34px 26px;
+  border: 1px solid rgba(111, 214, 244, 0.2);
+  border-left: 2px solid rgba(94, 244, 255, 0.82);
+  background:
+    linear-gradient(135deg, rgba(11, 19, 36, 0.88), rgba(6, 10, 22, 0.76) 58%, rgba(22, 8, 31, 0.66));
+  box-shadow: 0 34px 100px rgba(0, 0, 0, 0.58), inset 0 0 60px rgba(49, 110, 180, 0.07);
+  backdrop-filter: blur(14px);
+  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 0 100%);
+}
+.menu-card::after {
+  content: "";
+  position: absolute;
+  top: 0;
+  right: 26px;
+  width: 1px;
+  height: 26px;
+  background: rgba(94, 244, 255, 0.42);
+  transform: rotate(-45deg);
+  transform-origin: top right;
+}
+
+.eyebrow {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  color: #79a0b6;
+  font-size: 8px;
+  font-weight: 800;
+  letter-spacing: 0.28em;
+  text-transform: uppercase;
+}
+.eyebrow span { height: 1px; width: 24px; background: currentColor; opacity: 0.5; }
+
+.logo {
+  margin: 12px 0 8px;
+  font-family: "Arial Black", "Trebuchet MS", Impact, sans-serif;
+  font-size: clamp(58px, 8.2vw, 92px);
+  font-weight: 900;
+  font-style: italic;
+  line-height: 0.79;
+  letter-spacing: -0.075em;
+  text-transform: uppercase;
+  color: #f4fdff;
+  text-shadow: 0 0 26px rgba(94, 244, 255, 0.34), 0 16px 50px rgba(0, 0, 0, 0.55);
+}
+.logo em {
+  display: inline-block;
+  padding-right: 0.06em;
+  font-style: inherit;
+  background: linear-gradient(96deg, var(--magenta) 4%, #bd8bff 48%, var(--cyan) 100%);
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+  filter: drop-shadow(0 0 22px rgba(255, 79, 216, 0.28));
+}
+
+.tagline {
+  margin: 14px 0 20px;
+  max-width: 350px;
+  color: #9ab4c7;
+  font-size: 13px;
+  line-height: 1.55;
+  letter-spacing: 0.02em;
+}
+
+.primary, .secondary, .ghost {
+  position: relative;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 10px;
+  min-height: 50px;
+  padding: 0 24px;
+  border: 0;
+  border-radius: 2px;
+  cursor: pointer;
+  font-size: 12px;
+  font-weight: 900;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  transition: transform 140ms ease, box-shadow 140ms ease, background 140ms ease, color 140ms ease;
+}
+.primary {
+  color: #041018;
+  background: linear-gradient(96deg, #7ff8ff, #5ef4ff 46%, #bdfcff);
+  box-shadow: 0 0 0 1px rgba(140, 248, 255, 0.3), 0 12px 34px rgba(36, 191, 224, 0.24);
+  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
+}
+.primary:hover { transform: translateY(-1px); box-shadow: 0 0 0 1px rgba(180, 252, 255, 0.6), 0 16px 44px rgba(58, 220, 255, 0.34); }
+.primary:active { transform: translateY(1px) scale(0.995); }
+.secondary {
+  color: #dff9ff;
+  border: 1px solid rgba(94, 244, 255, 0.45);
+  background: rgba(14, 36, 52, 0.55);
+}
+.secondary:hover { background: rgba(24, 60, 82, 0.7); }
+.ghost {
+  color: #8ba5b8;
+  border: 1px solid rgba(122, 158, 184, 0.22);
+  background: transparent;
+}
+.ghost:hover { color: #e9fbff; border-color: rgba(142, 210, 235, 0.55); }
+
+#startBtn { width: 100%; justify-content: space-between; padding: 0 18px 0 24px; }
+#startBtn kbd {
+  display: inline-grid;
+  place-items: center;
+  width: 26px;
+  height: 26px;
+  border: 1px solid rgba(2, 24, 33, 0.26);
+  border-radius: 3px;
+  background: rgba(3, 27, 37, 0.14);
+  color: rgba(3, 24, 32, 0.78);
+  font-family: var(--mono);
+  font-size: 13px;
+}
+
+.menu-controls {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 8px 16px;
+  margin: 20px 0 18px;
+  padding-top: 16px;
+  border-top: 1px solid rgba(111, 197, 230, 0.14);
+}
+.menu-controls > div { display: flex; align-items: center; gap: 9px; min-width: 0; }
+.menu-controls > div > span:last-child { color: #87a4b9; font-size: 9px; letter-spacing: 0.08em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.keys { display: flex; gap: 3px; flex-shrink: 0; }
+kbd {
+  display: inline-grid;
+  place-items: center;
+  min-width: 19px;
+  height: 19px;
+  padding: 0 4px;
+  border: 1px solid rgba(124, 198, 226, 0.25);
+  border-bottom-color: rgba(94, 244, 255, 0.5);
+  border-radius: 3px;
+  background: rgba(13, 27, 43, 0.8);
+  color: #c7eaf5;
+  font-family: var(--mono);
+  font-size: 8px;
+  font-weight: 700;
+}
+
+.menu-footer {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 9px 18px;
+  padding-top: 14px;
+  border-top: 1px solid rgba(111, 197, 230, 0.14);
+}
+.menu-footer > div > span { display: block; color: #5d7b8f; font-size: 7px; font-weight: 800; letter-spacing: 0.18em; margin-bottom: 2px; }
+.menu-footer > div > b { color: #d7f6ff; font-family: var(--mono); font-size: 13px; font-weight: 700; letter-spacing: 0.01em; }
+.menu-footer .tip { grid-column: 1 / -1; color: #7090a3; font-size: 9px; line-height: 1.5; margin-top: 2px; }
+.menu-footer .tip b { color: #b8eaff; }
+
+.menu-side {
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+  margin-left: auto;
+  align-self: flex-end;
+  padding-bottom: 24px;
+}
+.side-chip {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  color: #7c9db0;
+  font-size: 8px;
+  font-weight: 700;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  opacity: 0.85;
+}
+.side-chip b {
+  font-family: var(--mono);
+  font-size: 10px;
+  color: var(--cyan);
+  border: 1px solid rgba(94, 244, 255, 0.25);
+  padding: 4px 6px;
+  background: rgba(5, 18, 28, 0.5);
+}
+
+.pause, .results {
+  align-items: center;
+  justify-content: center;
+  padding: 24px;
+  background: rgba(2, 5, 12, 0.66);
+  backdrop-filter: blur(7px);
+}
+
+.panel {
+  position: relative;
+  width: min(430px, 100%);
+  padding: 34px 36px 30px;
+  border: 1px solid rgba(109, 198, 230, 0.22);
+  border-top: 2px solid rgba(94, 244, 255, 0.7);
+  background: linear-gradient(150deg, rgba(11, 19, 36, 0.96), rgba(7, 11, 24, 0.96));
+  box-shadow: 0 34px 100px rgba(0, 0, 0, 0.6);
+  text-align: center;
+  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
+}
+.panel::after {
+  content: "";
+  position: absolute;
+  top: 0; right: 30px;
+  width: 70px; height: 1px;
+  background: var(--magenta);
+  box-shadow: 0 0 14px rgba(255, 79, 216, 0.8);
+}
+.panel .eyebrow { justify-content: center; }
+.panel h2 {
+  margin: 14px 0 6px;
+  font-family: "Arial Black", "Trebuchet MS", Impact, sans-serif;
+  font-size: 42px;
+  font-style: italic;
+  font-weight: 900;
+  line-height: 0.9;
+  letter-spacing: -0.04em;
+}
+.panel-sub { margin: 0 0 22px; color: #86a5b9; font-size: 11px; line-height: 1.5; }
+.button-stack { display: grid; gap: 9px; }
+.button-stack .primary, .button-stack .secondary, .button-stack .ghost { width: 100%; }
+
+.result-panel { width: min(480px, 100%); }
+#resultTitle {
+  font-size: 74px;
+  color: var(--amber);
+  background: linear-gradient(180deg, #fff6d8, #ffd166 62%, #ff9b54);
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+  text-shadow: 0 0 40px rgba(255, 177, 66, 0.2);
+}
+.result-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1px;
+  margin: 0 0 16px;
+  background: rgba(112, 185, 213, 0.14);
+  border: 1px solid rgba(112, 185, 213, 0.14);
+}
+.result-grid > div { padding: 14px 10px 12px; background: rgba(5, 11, 22, 0.92); }
+.result-grid span { display: block; color: #658397; font-size: 7px; font-weight: 800; letter-spacing: 0.18em; margin-bottom: 4px; }
+.result-grid b { display: block; color: #e7faff; font-family: var(--mono); font-size: 17px; letter-spacing: -0.02em; }
+.new-best {
+  display: none;
+  margin: 0 0 14px;
+  color: var(--lime);
+  font-family: var(--mono);
+  font-size: 10px;
+  font-weight: 800;
+  letter-spacing: 0.2em;
+  text-shadow: 0 0 16px rgba(168, 255, 120, 0.5);
+}
+.new-best.show { display: block; animation: newBest 1s ease-in-out infinite alternate; }
+@keyframes newBest { from { opacity: 0.55; } to { opacity: 1; } }
+.button-row { display: flex; gap: 10px; }
+.button-row .primary { flex: 1; }
+
+/* ---------------- Countdown, toasts, popups ---------------- */
+
+.countdown {
+  position: absolute;
+  inset: 0;
+  z-index: 17;
+  display: none;
+  place-items: center;
+  pointer-events: none;
+}
+.countdown.show { display: grid; }
+.countdown span {
+  display: block;
+  font-family: "Arial Black", "Trebuchet MS", Impact, sans-serif;
+  font-size: clamp(150px, 26vw, 300px);
+  font-weight: 900;
+  font-style: italic;
+  line-height: 0.8;
+  color: #f4feff;
+  text-shadow: 0 0 30px rgba(94, 244, 255, 0.7), 0 0 90px rgba(94, 244, 255, 0.3), 0 20px 50px rgba(0, 0, 0, 0.5);
+  transform: translateY(-4%);
+}
+.countdown span.go { color: var(--amber); text-shadow: 0 0 34px rgba(255, 209, 102, 0.8), 0 0 100px rgba(255, 79, 216, 0.4); }
+.countdown small { position: absolute; bottom: 29%; color: #8cc5d8; font-size: 10px; font-weight: 800; letter-spacing: 0.42em; opacity: 0; }
+.countdown.pop span { animation: countPop 480ms cubic-bezier(0.16, 1, 0.3, 1); }
+@keyframes countPop { 0% { transform: scale(1.7) translateY(-4%); opacity: 0; filter: blur(3px); } 100% { transform: scale(1) translateY(-4%); opacity: 1; filter: blur(0); } }
+
+.toast {
+  position: absolute;
+  top: 23%;
+  left: 50%;
+  z-index: 19;
+  transform: translate(-50%, -10px);
+  opacity: 0;
+  padding: 8px 16px;
+  border: 1px solid rgba(94, 244, 255, 0.28);
+  background: rgba(5, 15, 27, 0.82);
+  color: #c9f7ff;
+  font-family: var(--mono);
+  font-size: 10px;
+  font-weight: 800;
+  letter-spacing: 0.2em;
+  text-transform: uppercase;
+  pointer-events: none;
+  transition: opacity 180ms ease, transform 180ms ease;
+  backdrop-filter: blur(6px);
+}
+.toast.show { opacity: 1; transform: translate(-50%, 0); }
+.toast.warn { border-color: rgba(255, 79, 216, 0.45); color: #ffd7f6; }
+
+.popups { position: absolute; inset: 0; z-index: 15; pointer-events: none; overflow: hidden; }
+.scorepop {
+  position: absolute;
+  transform: translate(-50%, -50%);
+  font-family: var(--mono);
+  font-size: 13px;
+  font-weight: 800;
+  letter-spacing: 0.02em;
+  color: var(--cyan);
+  text-shadow: 0 0 14px rgba(94, 244, 255, 0.7), 0 2px 8px rgba(0, 0, 0, 0.8);
+  animation: scoreFloat 900ms ease-out forwards;
+  white-space: nowrap;
+}
+.scorepop.drift { color: var(--magenta); text-shadow: 0 0 14px rgba(255, 79, 216, 0.75), 0 2px 8px rgba(0, 0, 0, 0.8); }
+.scorepop.crash { color: #ff829d; font-size: 16px; }
+@keyframes scoreFloat {
+  0% { opacity: 0; transform: translate(-50%, -30%) scale(0.7); }
+  18% { opacity: 1; transform: translate(-50%, -60%) scale(1.08); }
+  100% { opacity: 0; transform: translate(-50%, -170%) scale(0.94); }
+}
+
+.hint-menu { display: none; }
+
+/* ---------------- Touch ---------------- */
+
+.touch-controls {
+  position: absolute;
+  left: 0;
+  right: 0;
+  bottom: 14px;
+  z-index: 24;
+  display: none;
+  align-items: flex-end;
+  justify-content: space-between;
+  padding: 0 14px;
+  pointer-events: none;
+}
+.touch-steer, .touch-pedals { display: flex; align-items: flex-end; gap: 9px; pointer-events: auto; }
+.touch-btn {
+  -webkit-tap-highlight-color: transparent;
+  border: 1px solid rgba(107, 214, 247, 0.4);
+  background: rgba(6, 18, 31, 0.62);
+  color: #d7f7ff;
+  border-radius: 50%;
+  width: 62px;
+  height: 62px;
+  display: grid;
+  place-items: center;
+  font-family: var(--mono);
+  font-size: 11px;
+  font-weight: 900;
+  letter-spacing: 0.04em;
+  backdrop-filter: blur(7px);
+  box-shadow: inset 0 0 20px rgba(70, 193, 230, 0.08), 0 8px 22px rgba(0, 0, 0, 0.35);
+  touch-action: none;
+}
+.touch-btn.pressed { background: rgba(24, 83, 107, 0.8); border-color: rgba(137, 248, 255, 0.9); transform: scale(0.96); box-shadow: 0 0 22px rgba(94, 244, 255, 0.36); }
+.touch-btn.gas { width: 78px; height: 78px; color: #061118; background: linear-gradient(160deg, #7ef8ff, #41d7e9); border: 0; font-size: 13px; box-shadow: 0 0 28px rgba(94, 244, 255, 0.28); }
+.touch-btn.drift { color: #ffd3f4; border-color: rgba(255, 79, 216, 0.5); }
+.touch-btn.small { width: 48px; height: 48px; font-size: 9px; }
+.touch-btn.steer { font-family: sans-serif; font-size: 20px; }
+
+@media (hover: none), (max-width: 760px) {
+  .touch-controls { display: flex; }
+  #app[data-state="menu"] .touch-controls,
+  #app[data-state="paused"] .touch-controls,
+  #app[data-state="finished"] .touch-controls { display: none; }
+}
+
+/* ---------------- Responsive ---------------- */
+
+@media (min-width: 900px) and (min-height: 600px) {
+  #app {
+    width: min(96vw, 1240px);
+    height: min(94vh, 790px);
+    border: 1px solid rgba(104, 194, 228, 0.18);
+    border-radius: 18px;
+    box-shadow: 0 40px 120px rgba(0, 0, 0, 0.62), 0 0 0 1px rgba(4, 9, 20, 0.9) inset;
+  }
+  #app > canvas, #app > .sky-glow, #app > .vignette, #app > .scanlines { border-radius: 18px; }
+}
+
+@media (max-width: 1050px) {
+  .menu-side { display: none; }
+  .menu-card { margin: 0 auto; }
+  .menu { justify-content: center; background: radial-gradient(ellipse at center, rgba(3, 7, 16, 0.5), rgba(2, 5, 12, 0.7)); }
+  .hud-top { gap: 4px; padding-left: 18px; padding-right: 88px; }
+  .hud-bottom { padding-left: 18px; padding-right: 18px; }
+  .gatebox { display: none; }
+}
+
+@media (max-width: 820px) {
+  .hud-top { padding-top: 14px; padding-left: 14px; padding-right: 82px; }
+  .hud-cluster { padding: 5px 8px 6px; }
+  .label { font-size: 7px; }
+  .big { font-size: 19px; }
+  .big b { font-size: 23px; }
+  .timebox { min-width: 0; }
+  .mono { font-size: 16px; }
+  .posbox { display: none; }
+  .scorebox { min-width: 106px; }
+  .scorebox .big.mono { font-size: 18px; }
+  .scorebox .combo { font-size: 9px; }
+  .tools { top: 12px; right: 12px; }
+  .hud-bottom { gap: 10px; padding: 38px 14px 18px; align-items: flex-end; }
+  .speedbox { width: 126px; }
+  .speed-read b { font-size: 36px; }
+  .speed-read span, .speed-hint { font-size: 7px; }
+  .driftbox { width: min(210px, 42vw); }
+  .mapbox { display: none; }
+  .menu { padding: 16px; align-items: flex-start; }
+  .menu-card { padding: 24px 22px 20px; margin-top: max(8px, 3vh); }
+  .logo { font-size: clamp(52px, 13vw, 72px); }
+  .tagline { font-size: 12px; margin-bottom: 16px; }
+  .menu-controls { gap: 7px 10px; margin: 16px 0 14px; }
+  .menu-controls > div > span:last-child { font-size: 8px; }
+  .menu-footer { gap: 8px 12px; }
+  .menu-footer .tip { font-size: 8px; }
+  .panel { padding: 28px 22px 24px; }
+  .panel h2 { font-size: 34px; }
+  #resultTitle { font-size: 60px; }
+  .countdown span { font-size: clamp(130px, 34vw, 220px); }
+}
+
+@media (max-width: 760px) {
+  .hud-bottom { bottom: 106px; padding-bottom: 8px; background: linear-gradient(0deg, rgba(2, 5, 12, 0.55), transparent); }
+  .driftbox { margin-bottom: 0; }
+  .speedbox { opacity: 0.92; }
+  .speed-read b { font-size: 32px; }
