export const TAU = Math.PI * 2;

export const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const mod = (value, length) => ((value % length) + length) % length;

export function wrapAngle(angle) {
  return Math.atan2(Math.sin(angle), Math.cos(angle));
}

export function shortestDelta(from, to, length) {
  return mod(to - from + length / 2, length) - length / 2;
}

export function distanceSq(ax, ay, bx, by) {
  const dx = ax - bx;
  const dy = ay - by;
  return dx * dx + dy * dy;
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a += 0x6d2b79f5;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function formatTime(seconds) {
  if (!Number.isFinite(seconds) || seconds < 0) return '--:--.---';
  const minutes = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  const millis = Math.floor((seconds % 1) * 1000);
  return `${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}.${String(millis).padStart(3, '0')}`;
}

export function formatScore(value) {
  return Math.floor(value).toLocaleString('en-US');
}

export function ordinal(value) {
  const n = Math.max(0, Math.floor(value));
  const rem10 = n % 10;
  const rem100 = n % 100;
  if (rem10 === 1 && rem100 !== 11) return `${n}st`;
  if (rem10 === 2 && rem100 !== 12) return `${n}nd`;
  if (rem10 === 3 && rem100 !== 13) return `${n}rd`;
  return `${n}th`;
}

import { clamp } from './core.js';

/**
 * Fully synthesised engine / tyre / UI audio. No external assets, no autoplay:
 * the context is created on the first user gesture (Start Race).
 */
export class GameAudio {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.ready = false;
    this.engineGain = null;
    this.engineFilter = null;
    this.engineOsc = null;
    this.engineOsc2 = null;
    this.skidGain = null;
    this.windGain = null;
  }

  init() {
    if (this.ready) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    try {
      const ctx = new Ctx();
      const master = ctx.createGain();
      master.gain.value = this.enabled ? 0.34 : 0;
      master.connect(ctx.destination);

      // Engine: two detuned saws through a soft low-pass.
      const engineGain = ctx.createGain();
      engineGain.gain.value = 0.0001;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 420;
      filter.Q.value = 3.6;
      engineGain.connect(filter);
      filter.connect(master);

      const oscA = ctx.createOscillator();
      oscA.type = 'sawtooth';
      oscA.frequency.value = 52;
      oscA.connect(engineGain);
      const oscB = ctx.createOscillator();
      oscB.type = 'square';
      oscB.frequency.value = 26;
      const subGain = ctx.createGain();
      subGain.gain.value = 0.4;
      oscB.connect(subGain);
      subGain.connect(engineGain);
      oscA.start();
      oscB.start();

      // Tyre screech: looped noise through a band-pass.
      const noiseBuffer = ctx.createBuffer(1, ctx.sampleRate * 1.5, ctx.sampleRate);
      const data = noiseBuffer.getChannelData(0);
      for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;
      const skidSource = ctx.createBufferSource();
      skidSource.buffer = noiseBuffer;
      skidSource.loop = true;
      const skidFilter = ctx.createBiquadFilter();
      skidFilter.type = 'bandpass';
      skidFilter.frequency.value = 1650;
      skidFilter.Q.value = 1.4;
      const skidGain = ctx.createGain();
      skidGain.gain.value = 0.0001;
      skidSource.connect(skidFilter);
      skidFilter.connect(skidGain);
      skidGain.connect(master);
      skidSource.start();

      // Wind rush for speed.
      const windSource = ctx.createBufferSource();
      windSource.buffer = noiseBuffer;
      windSource.loop = true;
      const windFilter = ctx.createBiquadFilter();
      windFilter.type = 'highpass';
      windFilter.frequency.value = 400;
      const windGain = ctx.createGain();
      windGain.gain.value = 0.0001;
      windSource.connect(windFilter);
      windFilter.connect(windGain);
      windGain.connect(master);
      windSource.start();

      this.ctx = ctx;
      this.master = master;
      this.engineGain = engineGain;
      this.engineFilter = filter;
      this.engineOsc = oscA;
      this.engineOsc2 = oscB;
      this.skidGain = skidGain;
      this.windGain = windGain;
      this.ready = true;
      if (ctx.state === 'suspended') ctx.resume().catch(() => {});
    } catch {
      this.ready = false;
    }
  }

  setEnabled(enabled) {
    this.enabled = enabled;
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(enabled ? 0.34 : 0, now, 0.04);
    if (enabled && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  update(speed, slip, throttle, boosting, active = true) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const norm = clamp(speed / 105, 0, 1);
    const gearBand = norm < 0.34 ? 0 : norm < 0.68 ? 1 : 2;
    const pitch = 46 + norm * 78 + gearBand * 9 + (boosting ? 24 : 0);
    this.engineOsc.frequency.setTargetAtTime(pitch, now, 0.07);
    this.engineOsc2.frequency.setTargetAtTime(pitch * 0.503, now, 0.07);
    this.engineFilter.frequency.setTargetAtTime(300 + norm * 920 + throttle * 190 + (boosting ? 500 : 0), now, 0.08);
    const engineTarget = active ? 0.048 + norm * 0.05 + Math.abs(throttle) * 0.018 + (boosting ? 0.03 : 0) : 0.0001;
    this.engineGain.gain.setTargetAtTime(engineTarget, now, 0.09);
    this.skidGain.gain.setTargetAtTime(active ? clamp((slip - 0.12) * 0.28, 0, 0.13) * (0.35 + norm) : 0.0001, now, 0.06);
    this.windGain.gain.setTargetAtTime(active ? clamp((norm - 0.25) * 0.05, 0, 0.035) : 0.0001, now, 0.12);
  }

  silence() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    this.engineGain.gain.setTargetAtTime(0.0001, now, 0.08);
    this.skidGain.gain.setTargetAtTime(0.0001, now, 0.05);
    this.windGain.gain.setTargetAtTime(0.0001, now, 0.1);
  }

  tone(freq, duration, type = 'square', volume = 0.08, slide = 0) {
    if (!this.ctx || !this.enabled) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, now);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), now + duration);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.03);
  }

  countdown(isGo = false) {
    this.tone(isGo ? 880 : 440, isGo ? 0.28 : 0.12, 'square', isGo ? 0.09 : 0.045, isGo ? 220 : 0);
  }

  gate() {
    this.tone(660, 0.08, 'triangle', 0.045);
    setTimeout(() => this.tone(990, 0.1, 'triangle', 0.04), 70);
  }

  crash() {
    if (!this.ctx || !this.enabled) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(120, now);
    osc.frequency.exponentialRampToValueAtTime(42, now + 0.22);
    gain.gain.setValueAtTime(0.16, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.26);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + 0.3);
  }

  boost() {
    this.tone(180, 0.32, 'sawtooth', 0.05, 500);
  }
}

const DRIVE_KEYS = new Set([
  'arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' ',
  'w', 'a', 's', 'd', 'shift'
]);

export class Input {
  constructor() {
    this.keys = new Set();
    this.touch = { left: false, right: false, gas: false, brake: false, drift: false, boost: false };
    this.onAction = null;
    this.bindKeyboard();
    this.bindTouch();
  }

  bindKeyboard() {
    window.addEventListener('keydown', (event) => {
      const key = event.key.toLowerCase();
      if (DRIVE_KEYS.has(key)) event.preventDefault();
      if (event.repeat) return;
      this.keys.add(key);
      const action = this.actionFor(key);
      if (action && this.onAction) this.onAction(action, event);
    }, { passive: false });

    window.addEventListener('keyup', (event) => {
      const key = event.key.toLowerCase();
      if (DRIVE_KEYS.has(key)) event.preventDefault();
      this.keys.delete(key);
    }, { passive: false });

    window.addEventListener('blur', () => this.keys.clear());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.keys.clear();
    });
  }

  actionFor(key) {
    if (key === 'enter' || key === ' ') return 'start';
    if (key === 'escape' || key === 'p') return 'pause';
    if (key === 'm') return 'mute';
    if (key === 'r') return 'restart';
    return null;
  }

  bindTouch() {
    document.querySelectorAll('[data-control]').forEach((button) => {
      const control = button.dataset.control;
      const press = (event) => {
        event.preventDefault();
        this.touch[control] = true;
        button.classList.add('pressed');
        if (button.setPointerCapture && event.pointerId !== undefined) {
          try { button.setPointerCapture(event.pointerId); } catch { /* ignore */ }
        }
      };
      const release = (event) => {
        if (event) event.preventDefault();
        this.touch[control] = false;
        button.classList.remove('pressed');
      };
      button.addEventListener('pointerdown', press);
      button.addEventListener('pointerup', release);
      button.addEventListener('pointercancel', release);
      button.addEventListener('lostpointercapture', release);
      button.addEventListener('contextmenu', (event) => event.preventDefault());
    });
  }

  get throttle() {
    return this.keys.has('w') || this.keys.has('arrowup') || this.touch.gas ? 1 : 0;
  }

  get brake() {
    return this.keys.has('s') || this.keys.has('arrowdown') || this.touch.brake ? 1 : 0;
  }

  get steer() {
    const left = this.keys.has('a') || this.keys.has('arrowleft') || this.touch.left;
    const right = this.keys.has('d') || this.keys.has('arrowright') || this.touch.right;
    return (right ? 1 : 0) - (left ? 1 : 0);
  }

  get handbrake() {
    return this.keys.has(' ') || this.touch.drift;
  }

  get boost() {
    return this.keys.has('shift') || this.touch.boost;
  }

  clear() {
    this.keys.clear();
    for (const key of Object.keys(this.touch)) this.touch[key] = false;
    document.querySelectorAll('.touch-btn.pressed').forEach((button) => button.classList.remove('pressed'));
  }
}

import { TAU, distanceSq, mod, mulberry32 } from './core.js';

const CONTROL_POINTS = [
  [60, 225], [-40, 205], [-105, 150], [-120, 80], [-190, 45],
  [-205, -60], [-185, -120], [-150, -160], [-20, -190], [110, -170],
  [190, -95], [185, 10], [120, 55], [70, 10], [35, -35],
  [5, 5], [30, 80], [110, 120], [140, 190]
];

const STEPS_PER_SEGMENT = 30;
const ROAD_HALF = 11.2;
const SHOULDER = 5.6;
const WALL = 16.6;

function catmullRom(p0, p1, p2, p3, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  return {
    x: 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
    y: 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3)
  };
}

export class Track {
  constructor() {
    this.roadHalf = ROAD_HALF;
    this.shoulder = SHOULDER;
    this.wall = WALL;
    this.points = this.sample();
    this.length = this.points[this.points.length - 1].s + this.segmentLength(this.points.length - 1, 0);
    this.checkpoints = [];
    for (let i = 0; i < 8; i += 1) {
      const fraction = i / 8;
      const point = this.pointAtDistance(fraction * this.length);
      this.checkpoints.push({ ...point, fraction, number: i + 1 });
    }
    this.props = this.buildProps();
    this.start = this.pointAtDistance(0);
  }

  sample() {
    const points = [];
    const count = CONTROL_POINTS.length;
    for (let i = 0; i < count; i += 1) {
      const p0 = CONTROL_POINTS[(i - 1 + count) % count];
      const p1 = CONTROL_POINTS[i];
      const p2 = CONTROL_POINTS[(i + 1) % count];
      const p3 = CONTROL_POINTS[(i + 2) % count];
      for (let step = 0; step < STEPS_PER_SEGMENT; step += 1) {
        points.push(catmullRom(p0, p1, p2, p3, step / STEPS_PER_SEGMENT));
      }
    }

    let distance = 0;
    for (let i = 0; i < points.length; i += 1) {
      const prev = points[(i - 1 + points.length) % points.length];
      const next = points[(i + 1) % points.length];
      const dx = next.x - prev.x;
      const dy = next.y - prev.y;
      const length = Math.hypot(dx, dy) || 1;
      points[i].tx = dx / length;
      points[i].ty = dy / length;
      points[i].nx = -points[i].ty;
      points[i].ny = points[i].tx;
      points[i].s = distance;
      const following = points[(i + 1) % points.length];
      distance += Math.hypot(following.x - points[i].x, following.y - points[i].y);
    }
    return points;
  }

  segmentLength(index, nextIndex) {
    const a = this.points[index];
    const b = this.points[nextIndex];
    return Math.hypot(b.x - a.x, b.y - a.y);
  }

  normalizeDistance(value) {
    return mod(value, this.length);
  }

  pointAtDistance(distance) {
    const d = this.normalizeDistance(distance);
    const points = this.points;
    let low = 0;
    let high = points.length - 1;
    while (low < high - 1) {
      const mid = (low + high) >> 1;
      if (points[mid].s <= d) low = mid;
      else high = mid;
    }
    const a = points[low];
    const index = (low + 1) % points.length;
    const b = points[index];
    const segment = Math.max(0.0001, b.s - a.s || this.length - a.s);
    const t = Math.max(0, Math.min(1, (d - a.s) / segment));
    const x = a.x + (b.x - a.x) * t;
    const y = a.y + (b.y - a.y) * t;
    const tx = a.tx + (b.tx - a.tx) * t;
    const ty = a.ty + (b.ty - a.ty) * t;
    const tl = Math.hypot(tx, ty) || 1;
    return {
      x,
      y,
      tx: tx / tl,
      ty: ty / tl,
      nx: -ty / tl,
      ny: tx / tl,
      s: d,
      index: low
    };
  }

  lanePoint(distance, offset) {
    const p = this.pointAtDistance(distance);
    return { ...p, x: p.x + p.nx * offset, y: p.y + p.ny * offset };
  }

  nearest(x, y) {
    const points = this.points;
    let best = 0;
    let bestDist = Infinity;
    for (let i = 0; i < points.length; i += 1) {
      const p = points[i];
      const dx = x - p.x;
      const dy = y - p.y;
      const d = dx * dx + dy * dy;
      if (d < bestDist) {
        bestDist = d;
        best = i;
      }
    }
    const p = points[best];
    const dx = x - p.x;
    const dy = y - p.y;
    const distance = Math.sqrt(bestDist);
    return {
      index: best,
      s: p.s,
      distance,
      x: p.x,
      y: p.y,
      nx: distance > 0.0001 ? dx / distance : p.nx,
      ny: distance > 0.0001 ? dy / distance : p.ny,
      tx: p.tx,
      ty: p.ty,
      roadHalf: ROAD_HALF
    };
  }

  distanceToTrack(x, y) {
    return this.nearest(x, y).distance;
  }

  buildProps() {
    const random = mulberry32(20261106);
    const buildings = [];
    const palette = [
      ['#1a1d3a', '#2a2352', '#0c1024', '#5ef4ff'],
      ['#241638', '#371b4d', '#100b20', '#ff4fd8'],
      ['#0f2436', '#16374c', '#08111e', '#5ef4ff'],
      ['#251c2c', '#332545', '#0e0b16', '#ffd166'],
      ['#121d2a', '#1a2b3d', '#080d15', '#a8ff78']
    ];

    let attempts = 0;
    while (buildings.length < 34 && attempts < 900) {
      attempts += 1;
      const x = (random() - 0.5) * 620;
      const y = (random() - 0.5) * 620;
      const w = 16 + random() * 26;
      const d = 16 + random() * 26;
      const radius = Math.max(w, d) * 0.65;
      if (this.distanceToTrack(x, y) < 29 + radius) continue;
      let overlaps = false;
      for (const other of buildings) {
        if (Math.abs(x - other.x) < (w + other.w) * 0.72 + 4 && Math.abs(y - other.y) < (d + other.d) * 0.72 + 4) {
          overlaps = true;
          break;
        }
      }
      if (overlaps) continue;
      const scheme = palette[Math.floor(random() * palette.length)];
      const height = 12 + random() * random() * 62;
      buildings.push({
        type: 'building',
        x,
        y,
        w,
        d,
        h: height,
        dark: scheme[0],
        mid: scheme[1],
        deep: scheme[2],
        glow: scheme[3],
        windows: 2 + Math.floor(random() * 4),
        floors: 2 + Math.floor(random() * 5),
        seed: random() * 1000
      });
    }

    const pylons = [];
    for (let i = 3; i < this.points.length; i += 13) {
      const p = this.points[i];
      const side = Math.floor(i / 13) % 2 === 0 ? 1 : -1;
      const offset = 19.5 + random() * 3;
      pylons.push({
        type: 'pylon',
        x: p.x + p.nx * offset * side,
        y: p.y + p.ny * offset * side,
        h: 5.5 + random() * 5,
        color: random() > 0.42 ? '#5ef4ff' : '#ff4fd8',
        seed: random() * 100
      });
    }

    const specks = [];
    for (let i = 0; i < 150; i += 1) {
      const x = (random() - 0.5) * 760;
      const y = (random() - 0.5) * 760;
      if (this.distanceToTrack(x, y) < 15) continue;
      specks.push({
        x,
        y,
        size: 1 + random() * 2.3,
        color: random() > 0.78 ? '#ff4fd8' : random() > 0.45 ? '#5ef4ff' : '#8b7dff',
        phase: random() * TAU
      });
    }

    const signs = [
      { fraction: 0.19, offset: 25, text: 'NEON', color: '#5ef4ff' },
      { fraction: 0.49, offset: 26, text: 'DRIFT', color: '#ff4fd8' },
      { fraction: 0.72, offset: 24, text: 'N2O', color: '#ffd166' }
    ].map((sign) => {
      const p = this.pointAtDistance(sign.fraction * this.length);
      return {
        type: 'sign',
        x: p.x + p.nx * sign.offset,
        y: p.y + p.ny * sign.offset,
        h: 11,
        text: sign.text,
        color: sign.color
      };
    });

    return { buildings, pylons, specks, signs };
  }
}

