`updateCamera`:
```
const menu=state==='menu';
let focusX, focusY, zoomTarget;
if menu { const ai=this.ai[0]; focusX=ai.x+cos(angle)*12; ... zoomTarget=base*.9}
else { focusX=player.x+player.vx*.36; focusY=...; zoomTarget=base*(1-clamp(speed/190,0,.1)) }
camera.x=damp(camera.x,focusX,menu?2.4:4.2,dt); ...
