`finishRace`:
```
this.state='finished';
this.lap=3;
this.updatePosition(); // AI progress maybe ahead
const position=this.position;
const newBest=!this.best.bestTime||this.time<this.best.bestTime;
this.best.bestTime = newBest? this.time : this.best.bestTime;
