await page.goto('http://127.0.0.1:3210/', { waitUntil: 'networkidle' });
await page.getByLabel('Start game').click();
await page.waitForTimeout(3600);
await page.evaluate(() => {
  const g = window.__neonDrift.game;
  g.ai.forEach((ai, i) => { ai.progress += 130 + i * 20; });
  const inp = g.input;
  inp.keys.add('w');
  window.__auto = setInterval(() => {
    const p = g.player;
    const near = g.track.nearest(p.x, p.y);
    const look = 12 + p.speed * 0.28;
    const target = g.track.pointAtDistance(near.s + look);
    let diff = Math.atan2(target.y - p.y, target.x - p.x) - p.angle;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    inp.keys.delete('a');
    inp.keys.delete('d');
    if (diff > 0.035) inp.keys.add('d');
    else if (diff < -0.035) inp.keys.add('a');
  }, 16);
});
await page.waitForTimeout(4200);
console.log('fps check start');
const fps = await page.evaluate(() => new Promise((resolve) => {
  let frames = 0;
  const start = performance.now();
  function tick(now) {
    frames += 1;
    if (now - start < 1000) requestAnimationFrame(tick);
    else resolve(Math.round(frames * 1000 / (now - start)));
  }
  requestAnimationFrame(tick);
}));
console.log('fps', fps);
await page.screenshot({ path: '/tmp/opencode/drive3.jpg', type: 'jpeg', quality: 86 });
const carPos = await page.evaluate(() => {
  const g = window.__neonDrift.game;
  const p = g.renderer.project(g.player.x, g.player.y, 0);
  return { x: p.x, y: p.y, speed: Math.round(g.player.speed), total: Math.round(g.total), offRoad: g.offRoad, state: g.state };
});
console.log('drive', carPos);
const clip = { x: Math.max(0, carPos.x - 210), y: Math.max(0, carPos.y - 150), width: 420, height: 300 };
if (clip.x + clip.width > 1200) clip.x = 1200 - clip.width;
if (clip.y + clip.height > 800) clip.y = 800 - clip.height;
await page.screenshot({ path: '/tmp/opencode/carclose.jpg', type: 'jpeg', quality: 90, clip });
await page.evaluate(() => {
  const g = window.__neonDrift.game;
  g.input.keys.add(' ');
  g.input.keys.add('d');
});
await page.waitForTimeout(1300);
await page.screenshot({ path: '/tmp/opencode/drift3.jpg', type: 'jpeg', quality: 86 });
console.log('drift', await page.evaluate(() => {
  const g = window.__neonDrift.game;
  return { speed: Math.round(g.player.speed), slip: Math.round(g.player.slip * 180 / Math.PI), drift: g.drifting, score: Math.round(g.score), nitro: Math.round(g.nitro), mult: +g.multiplier.toFixed(2), offRoad: g.offRoad, particles: g.particles.length, skids: g.skids.length };
}));
await page.evaluate(() => { clearInterval(window.__auto); window.__neonDrift.game.input.clear(); });
await page.waitForTimeout(300);
await page.getByLabel('Pause race').click();
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/pause.jpg', type: 'jpeg', quality: 84 });
await page.evaluate(() => {
  const g = window.__neonDrift.game;
  g.time = 83.421;
  g.bestLap = 26.114;
  g.score = 12480;
  g.topSpeed = 238;
  g.position = 2;
  g.finishRace();
});
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/results.jpg', type: 'jpeg', quality: 84 });
console.log('results state', await page.evaluate(() => window.__neonDrift.game.state));
console.log('errors', JSON.stringify(errors));
await browser.close();

import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 }, deviceScaleFactor: 1 });
await page.goto('http://127.0.0.1:3210/', { waitUntil: 'networkidle' });
await page.getByLabel('Start game').click();
await page.waitForTimeout(3700);
const result = await page.evaluate(() => new Promise((resolve) => {
  const g = window.__neonDrift.game;
  const r = g.renderer;
  const names = ['drawBackground', 'drawGrid', 'drawSpecks', 'drawTrack', 'drawSkids', 'drawGates', 'drawWorld', 'drawParticles', 'drawSpeedLines'];
  const times = {};
  for (const name of names) {
    const original = r[name].bind(r);
    r[name] = (...args) => {
      const t = performance.now();
      const out = original(...args);
      times[name] = (times[name] || 0) + performance.now() - t;
      return out;
    };
  }
  const originalDraw = r.draw.bind(r);
  let drawTime = 0;
  let frames = 0;
  r.draw = (...args) => {
    const t = performance.now();
    const out = originalDraw(...args);
    drawTime += performance.now() - t;
    frames += 1;
    return out;
  };
  const start = performance.now();
  setTimeout(() => {
    for (const key of Object.keys(times)) times[key] = +(times[key] / frames).toFixed(2);
    resolve({ frames, seconds: +((performance.now() - start) / 1000).toFixed(2), avgDraw: +(drawTime / frames).toFixed(2), times });
  }, 2000);
}));
console.log(JSON.stringify(result, null, 2));
await browser.close();

