import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (error) => errors.push(error.message));
await page.goto('http://127.0.0.1:3210/', { waitUntil: 'networkidle' });
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/mobile-menu.jpg', type: 'jpeg', quality: 86 });
console.log('touch display', await page.locator('#touchControls').evaluate((el) => getComputedStyle(el).display));
await page.getByLabel('Start game').click();
await page.waitForTimeout(3800);
await page.evaluate(() => {
  const g = window.__neonDrift.game;
  g.ai.forEach((ai, i) => { ai.progress += 140 + i * 16; });
  g.input.keys.add('w');
  window.__auto = setInterval(() => {
    const p = g.player;
    const near = g.track.nearest(p.x, p.y);
    const target = g.track.pointAtDistance(near.s + 14 + p.speed * 0.28);
    let diff = Math.atan2(target.y - p.y, target.x - p.x) - p.angle;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    g.input.keys.delete('a');
    g.input.keys.delete('d');
    if (diff > 0.04) g.input.keys.add('d');
    else if (diff < -0.04) g.input.keys.add('a');
  }, 16);
});
await page.waitForTimeout(3500);
await page.screenshot({ path: '/tmp/opencode/mobile-race.jpg', type: 'jpeg', quality: 86 });
console.log(await page.evaluate(() => {
  const g = window.__neonDrift.game;
  return { state: g.state, speed: Math.round(g.player.speed), total: Math.round(g.total), offRoad: g.offRoad, touch: g.input.touch, buttons: [...document.querySelectorAll('.touch-btn')].map((b) => ({ label: b.dataset.control, display: getComputedStyle(b).display })) };
}));
await page.evaluate(() => { clearInterval(window.__auto); window.__neonDrift.game.input.clear(); });
console.log('errors', errors);
await browser.close();

