import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://127.0.0.1:3210/', { waitUntil: 'networkidle' });
await page.getByLabel('Start game').click();
await page.waitForTimeout(3400);
const result = await page.evaluate(() => {
  const g = window.__neonDrift.game;
  g.ai.forEach((a, i) => { a.progress = 9000 + i * 20; a.speed = 55; });
  g.hud.update = () => {};
  g.hud.toast = () => {};
  g.hud.popup = () => {};
  g.hud.flash = () => {};
  g.audio.silence = () => {};
  const inp = g.input;
  let crashes = 0;
  const oldCrash = g.onCrash.bind(g);
  g.onCrash = (force) => { if (g.crashCooldown <= 0) crashes += 1; oldCrash(force); };
  const snapshots = [];
  for (let i = 0; i < 24000; i += 1) {
    if (g.state !== 'race') break;
    const p = g.player;
    const near = g.track.nearest(p.x, p.y);
    const target = g.track.pointAtDistance(near.s + 12 + p.speed * 0.32);
    let diff = Math.atan2(target.y - p.y, target.x - p.x) - p.angle;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    const ahead1 = g.track.pointAtDistance(near.s + 35);
    const ahead2 = g.track.pointAtDistance(near.s + 70);
    const dot = Math.max(-1, Math.min(1, ahead1.tx * ahead2.tx + ahead1.ty * ahead2.ty));
    const curve = Math.acos(dot);
    const targetSpeed = Math.max(25, 60 - curve * 26);
    inp.keys.add('w');
    inp.keys.delete('s');
    inp.keys.delete('a');
    inp.keys.delete('d');
    inp.keys.delete(' ');
    if (diff > 0.04) inp.keys.add('d');
    else if (diff < -0.04) inp.keys.add('a');
    if (p.speed > targetSpeed + 3) { inp.keys.delete('w'); inp.keys.add('s'); }
    if (Math.abs(diff) > 0.3 && p.speed > 32) inp.keys.add(' ');
    g.update(1 / 120);
    if (i % 1200 === 0) snapshots.push({ i, state: g.state, lap: g.lap, gate: g.nextGate, total: Math.round(g.total), speed: Math.round(p.speed), time: +g.time.toFixed(1), score: Math.round(g.score) });
  }
  inp.clear();
  return {
    state: g.state,
    time: +g.time.toFixed(2),
    lap: g.lap,
    lapIndex: g.lapIndex,
    nextGate: g.nextGate,
    total: Math.round(g.total),
    bestLap: +g.bestLap.toFixed(2),
    score: Math.round(g.score),
    crashes,
    result: g.result,
    aiProgress: g.ai.map((a) => Math.round(a.progress)),
    snapshots
  };
});
console.log(JSON.stringify(result, null, 2));
console.log('errors', errors);
await browser.close();

