import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const failures = [];
page.on('pageerror', (e) => failures.push(`pageerror ${e.message}`));
page.on('response', (r) => { if (r.status() >= 400) failures.push(`http ${r.status()} ${r.url()}`); });
await page.goto('http://127.0.0.1:3210/', { waitUntil: 'networkidle' });
await page.getByLabel('Start game').click();
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/start1s.jpg', type: 'jpeg', quality: 85 });
await page.waitForTimeout(2800);
await page.evaluate(() => {
  const g = window.__neonDrift.game;
  g.ai.forEach((ai, i) => { ai.progress += 180 + i * 16; });
  g.input.keys.add('w');
  window.__auto = setInterval(() => {
    const p = g.player;
    const near = g.track.nearest(p.x, p.y);
    const target = g.track.pointAtDistance(near.s + 14 + p.speed * 0.27);
    let diff = Math.atan2(target.y - p.y, target.x - p.x) - p.angle;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    g.input.keys.delete('a'); g.input.keys.delete('d');
    if (diff > 0.04) g.input.keys.add('d');
    else if (diff < -0.04) g.input.keys.add('a');
  }, 16);
});
await page.waitForTimeout(4000);
await page.screenshot({ path: '/tmp/opencode/race-final.jpg', type: 'jpeg', quality: 86 });
const pos = await page.evaluate(() => {
  const g = window.__neonDrift.game;
  const p = g.renderer.project(g.player.x, g.player.y, 0);
  return { x: p.x, y: p.y };
});
const clip = { x: Math.max(0, pos.x - 190), y: Math.max(0, pos.y - 140), width: 380, height: 280 };
await page.screenshot({ path: '/tmp/opencode/car-final.jpg', type: 'jpeg', quality: 92, clip });
await page.screenshot({ path: '/tmp/opencode/map-final.jpg', type: 'jpeg', quality: 92, clip: { x: 1000, y: 610, width: 280, height: 190 } });
await page.evaluate(() => { clearInterval(window.__auto); window.__neonDrift.game.input.clear(); });
console.log('desktop', await page.evaluate(() => ({ state: window.__neonDrift.game.state, speed: Math.round(window.__neonDrift.game.player.speed) })));
await page.close();

const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const mobile = await context.newPage();
mobile.on('pageerror', (e) => failures.push(`mobile pageerror ${e.message}`));
await mobile.goto('http://127.0.0.1:3210/', { waitUntil: 'networkidle' });
await mobile.getByLabel('Start game').click();
await mobile.waitForTimeout(3600);
const gas = mobile.locator('[data-control="gas"]');
await gas.dispatchEvent('pointerdown', { pointerId: 1, pointerType: 'touch', isPrimary: true });
await mobile.waitForTimeout(1500);
const touchState = await mobile.evaluate(() => {
  const g = window.__neonDrift.game;
  return { state: g.state, speed: Math.round(g.player.speed), gas: g.input.touch.gas, total: Math.round(g.total) };
});
await gas.dispatchEvent('pointerup', { pointerId: 1, pointerType: 'touch', isPrimary: true });
await mobile.screenshot({ path: '/tmp/opencode/mobile-race2.jpg', type: 'jpeg', quality: 86 });
console.log('touch', touchState);
console.log('failures', failures);
await browser.close();

